/**
 * Retry a function with exponential backoff and jitter.
 * @param fn - Async function to retry
 * @param attempts - Number of attempts (default: 3)
 * @param baseMs - Base delay in milliseconds (default: 100)
 * @returns Promise resolving to the function result
 * @throws Last error if all attempts fail
 */
export async function retry<T>(fn: () => Promise<T>, attempts = 3, baseMs = 100): Promise<T> {
  let lastErr: unknown;
  // Loop through each attempt
  for (let i = 0; i < attempts; i++) {
    try {
      // Try to execute the function
      return await fn();
    } catch (err) {
      // Store the error for later throwing if all attempts fail
      lastErr = err;
      // If not the last attempt, wait before retrying
      if (i < attempts - 1) {
        // Calculate exponential backoff with jitter: baseMs * 2^i + random delay
        const delay = baseMs * 2 ** i + Math.random() * baseMs;
        // Wait before the next attempt
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }
  // Throw the last error if all attempts failed
  throw lastErr;
}
