/**
 * Runs an async function, retrying on failure with exponential backoff + jitter.
 *
 * @param fn - The async operation to attempt.
 * @param attempts - Maximum number of tries before giving up (default 3).
 * @param baseMs - Base delay in ms used to compute backoff (default 100).
 * @returns The resolved value of `fn` on the first successful attempt.
 * @throws The last error encountered if all attempts fail.
 */
export async function retry<T>(fn: () => Promise<T>, attempts = 3, baseMs = 100): Promise<T> {
  // Holds the most recent error so it can be rethrown if every attempt fails.
  let lastErr: unknown;

  // Try up to `attempts` times.
  for (let i = 0; i < attempts; i++) {
    try {
      // Success: return immediately, skipping any remaining retries.
      return await fn();
    } catch (err) {
      // Remember this failure in case it turns out to be the last one.
      lastErr = err;

      // Only wait/backoff if there are more attempts left.
      if (i < attempts - 1) {
        // Exponential backoff (baseMs * 2^i) plus random jitter to avoid
        // thundering-herd retries from many callers at once.
        const delay = baseMs * 2 ** i + Math.random() * baseMs;
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }

  // All attempts exhausted — surface the final error to the caller.
  throw lastErr;
}
